namespace ShipmentTracker.Services;

public static class SeedData
{
    public static async Task InitializeAsync(ApplicationDbContext db)
    {
        if (db.Shipments.Any()) return;

        var shipments = new List<Shipment>
        {
            new()
            {
                TrackingNumber = "SHP-20260620-10001",
                Origin = "New York, NY",
                Destination = "London, UK",
                Status = ShipmentStatus.InTransit,
                ShippedDate = DateTime.UtcNow.AddDays(-3),
                EstimatedDelivery = DateTime.UtcNow.AddDays(4),
                RecipientName = "James Wilson",
                RecipientEmail = "james@example.com",
                Description = "Electronics - Laptop"
            },
            new()
            {
                TrackingNumber = "SHP-20260619-10002",
                Origin = "Tokyo, Japan",
                Destination = "Sydney, Australia",
                Status = ShipmentStatus.OutForDelivery,
                ShippedDate = DateTime.UtcNow.AddDays(-5),
                EstimatedDelivery = DateTime.UtcNow.AddDays(1),
                RecipientName = "Sarah Chen",
                RecipientEmail = "sarah@example.com",
                Description = "Medical Supplies"
            },
            new()
            {
                TrackingNumber = "SHP-20260618-10003",
                Origin = "Berlin, Germany",
                Destination = "São Paulo, Brazil",
                Status = ShipmentStatus.Delivered,
                ShippedDate = DateTime.UtcNow.AddDays(-10),
                EstimatedDelivery = DateTime.UtcNow.AddDays(-2),
                ActualDelivery = DateTime.UtcNow.AddDays(-3),
                RecipientName = "Carlos Silva",
                RecipientEmail = "carlos@example.com",
                Description = "Auto Parts"
            },
            new()
            {
                TrackingNumber = "SHP-20260621-10004",
                Origin = "Shanghai, China",
                Destination = "Los Angeles, CA",
                Status = ShipmentStatus.PickedUp,
                ShippedDate = DateTime.UtcNow.AddDays(-1),
                EstimatedDelivery = DateTime.UtcNow.AddDays(6),
                RecipientName = "Mike Johnson",
                RecipientEmail = "mike@example.com",
                Description = "Clothing - Bulk Order"
            },
            new()
            {
                TrackingNumber = "SHP-20260622-10005",
                Origin = "Mumbai, India",
                Destination = "Dubai, UAE",
                Status = ShipmentStatus.Exception,
                ShippedDate = DateTime.UtcNow.AddDays(-4),
                EstimatedDelivery = DateTime.UtcNow.AddDays(2),
                RecipientName = "Ahmed Hassan",
                RecipientEmail = "ahmed@example.com",
                Description = "Textiles - Customs Hold"
            },
            new()
            {
                TrackingNumber = "SHP-20260623-10006",
                Origin = "Paris, France",
                Destination = "Toronto, Canada",
                Status = ShipmentStatus.Pending,
                ShippedDate = DateTime.UtcNow,
                EstimatedDelivery = DateTime.UtcNow.AddDays(7),
                RecipientName = "Marie Dupont",
                RecipientEmail = "marie@example.com",
                Description = "Cosmetics - Fragile"
            }
        };

        db.Shipments.AddRange(shipments);
        await db.SaveChangesAsync();
    }
}

